import sys

def find_min_k(n, f):
    def apply_f_k_times(x, k):
        for _ in range(k):
            x = f[x - 1]
        return x

    for k in range(1, n + 1):
        if all(apply_f_k_times(x, k) == apply_f_k_times(apply_f_k_times(x, k), k) for x in range(1, n + 1)):
            return k

n = int(sys.stdin.readline().strip())
f = list(map(int, sys.stdin.readline().strip().split()))
print(find_min_k(n, f))
